mapper.select:
SELECT id, conversation_id, role, content, status, model_id, sequence_no, error_code, generation_id, created_at, updated_at
FROM messages WHERE conversation_id = #{conversationId}
ORDER BY sequence_no ASC

mapper.update:
UPDATE messages
SET content = #{content}, status = #{status}, error_code = #{errorCode}, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE messages
SET content = #{content}, status = #{status}, error_code = #{errorCode}, updated_at = #{updatedAt}
WHERE id = #{id} AND generation_id = #{generationId} AND status = 'STREAMING'
  AND EXISTS (
      SELECT 1 FROM chat_generations
      WHERE id = #{generationId} AND fence_epoch = #{epoch} AND status = #{generationStatus}
  )

UPDATE messages
SET status = 'FAILED', error_code = #{errorCode}, updated_at = #{updatedAt}
WHERE status = 'STREAMING' AND updated_at < #{cutoff}
